import{_ as t,o,c as a,ag as r}from"./chunks/framework.BIas3y6W.js";const g=JSON.parse('{"title":"Week 8 — Own It","description":"","frontmatter":{"source":"weeks/08-own-it/README.md"},"headers":[],"relativePath":"weeks/08-own-it/index.md","filePath":"weeks/08-own-it/index.md"}'),s={name:"weeks/08-own-it/index.md"};function i(n,e,h,d,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="week-8--own-it" tabindex="-1">Week 8 — Own It <a class="header-anchor" href="#week-8--own-it" aria-label="Permalink to &quot;Week 8 — Own It&quot;">​</a></h1><blockquote><p>If you can&#39;t explain it, you didn&#39;t build it.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (30 min at most)</td><td>Read this page and <a href="./../../assessment/oral-walkthroughs.html#what-to-expect">What to expect</a> on the oral walkthroughs page (5 minutes), then the <a href="#before-class">Before class</a> list</td></tr><tr><td><strong>Studio A</strong></td><td>Concept talk and live demo: your history, and tests for your own logic. Lab: <code>git log</code>, <code>git diff</code> and <code>git revert</code> (🔴 AI off), then tests for your Project 1, while <strong>oral walkthrough 1</strong> slots begin</td></tr><tr><td><strong>Studio B</strong></td><td>Show and tell. &quot;<strong>You write it</strong>&quot;: a function you write yourself from a short spec, test first. Project work time with walkthrough slots. Exit ticket (🔴 AI off)</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before)</td><td><strong>Project 1 final:</strong> every MUST criterion passing on GitHub Pages · at least <strong>three automated tests</strong> of your pure logic · <code>TESTS.md</code> complete, with at least three edge cases · the function you wrote yourself · <code>SPEC.md</code>, <code>README.md</code>, <code>PROMPTS.md</code> up to date · reflection and <strong>mid-course survey</strong> on Canvas · walkthrough 1 done. Details: <a href="./homework.html">homework</a></td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: fixing and finishing Project 1 (Copilot <strong>Ask</strong> mode or a chat assistant; no agent mode yet) · 🟡 AI limited: &quot;You write it&quot; (Ask mode reviews the function you wrote) and your tests (the AI may explain output and suggest cases; you write the tests) · 🔴 AI off: the git practice, walkthrough 1, the reflection, the survey, the exit ticket</td></tr><tr><td><strong>Must read</strong></td><td>This page, the <a href="./lab.html">lab</a>, the <a href="./homework.html">homework</a>, and &quot;What to expect&quot; on the <a href="./../../assessment/oral-walkthroughs.html#what-to-expect">oral walkthroughs</a> page</td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./../../resources/git-cheatsheet.html">Git Cheat Sheet</a> · <a href="./../../templates/TESTS.html">TESTS template</a> · your first test in <a href="./../04-undo-compare-explain/">week 4</a> · the <a href="https://github.com/Boyu-Zhang-UOI/vc101-rescue-study-timer" target="_blank" rel="noreferrer">rescue starter</a>&#39;s tests, as examples · <a href="./../../projects/project-1-useful-tool.html">Project 1 brief</a> · <a href="./../../resources/glossary.html">Glossary</a> · <a href="./../../resources/troubleshooting.html">Troubleshooting</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>Project 1 is live, and <code>npm test</code> runs at least three passing tests of your own logic. Week 9 starts from a Node project with tests</td></tr><tr><td><strong>Time</strong></td><td>Studios 2½ h · outside about 6 h (prep 30 min, homework core about 3 h, project time about 2 h, <code>PROMPTS.md</code>, reflection and survey about 40 min); stretch is optional</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>See your history and changes with <code>git log</code>, <code>git show</code> and <code>git diff</code>, throw away an uncommitted change with <code>git restore</code>, and undo a bad commit with <code>git revert</code>.</li><li>Explain your own Project 1 out loud, with the AI off: a function, your save and load lines, and your history.</li><li>Write a function yourself from a short spec, test first, and have Copilot&#39;s Ask mode review it.</li><li>Choose what to test in your own app (the normal case, the boundaries, the empty case) and write automated tests for its pure logic with <code>node --test</code>.</li><li>Show that each test can fail, by breaking the code on purpose.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ Your week 7 fixes are committed and pushed, and your README&#39;s acceptance table is honest.</li><li>☐ Read <a href="./../../assessment/oral-walkthroughs.html#what-to-expect">What to expect</a>, and know when your walkthrough 1 slot is.</li><li>☐ In your Project 1 Codespace, run <code>npm test</code>: it should run your week 6 test. No <code>package.json</code> yet? Lab Part A2 shows how to add one.</li><li>☐ Copilot is on (<a href="./../../setup/accounts.html">accounts</a>), with <strong>Chat: Disable AI Features</strong> unticked again after the clinic. The Copilot icon in the status bar shows this month&#39;s allowance: Ask mode uses some.</li></ul><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap, concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-08.html" target="_blank" rel="noreferrer">slides</a>) and a live demo. Lab: git log, diff and revert (🔴 AI off), then tests for your Project 1 logic; <strong>oral walkthrough 1</strong> slots start once everyone has practiced <code>git revert</code>. Checkpoint share</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell. Mini-lesson and lab: &quot;You write it&quot;. Project work time with walkthrough slots. Exit ticket (🔴 AI off)</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="./lab.html">Lab</a></td><td>Step-by-step, both studios, including the function cards (must read)</td></tr><tr><td><a href="./homework.html">Homework</a></td><td>Project 1 final, with the deliverables checklist (must read)</td></tr><tr><td><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-08.html" target="_blank" rel="noreferrer">Slides</a></td><td>The concept talk and the Studio B mini-lesson</td></tr><tr><td>Templates: <a href="./../../templates/TESTS.html">TESTS</a> · <a href="./../../templates/PROMPTS.html">PROMPTS</a> · <a href="./../../templates/PROJECT_README.html">Project README</a></td><td>For your Project 1 repository</td></tr><tr><td><a href="./../../assessment/oral-walkthroughs.html">Oral walkthroughs</a></td><td>&quot;What to expect&quot;, and Walkthrough 1&#39;s published questions</td></tr><tr><td><a href="./../../assessment/rubrics.html#project-1">Project 1 rubric</a></td><td>How the final version is graded</td></tr></tbody></table><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>If you&#39;re working through this week on your own, read this section, then do the <a href="./lab.html">lab</a>. The <a href="./../../resources/self-paced.html">self-paced path</a> says what to do instead of the walkthrough and the pair activities.</p><p><strong>Your history is a debugging tool.</strong> <code>git log --oneline</code> lists your save points; <code>git diff</code> shows exactly what changed since the last one; <code>git revert</code> undoes a commit by adding a new commit, so nothing is lost. When something worked yesterday and doesn&#39;t today, the answer is in the history. Never use <code>git reset --hard</code> or <code>git push --force</code> to undo work: they delete history (<a href="./../../resources/git-cheatsheet.html#revert-vs-reset">Revert vs reset</a>).</p><p><strong>Own it: walkthrough 1.</strong> A 10-minute conversation with the AI off, on your own Project 1: explain a function, find the failing line after the examiner breaks one line, fix it, then commit and revert a change. The questions are published. It&#39;s not a trick test, and it can be retaken once.</p><p><strong>You write it; the AI reviews.</strong> Copilot has three modes: <em>inline suggestions</em> (grey text as you type), <em><a href="./../../resources/glossary.html#ask-mode">Ask</a></em> (a chat that answers without changing your files) and <em>Agent</em> (edits files and runs commands itself). This week uses <strong>Ask only</strong>, with suggestions switched off while you write. You get a short spec for one function (inputs, output, examples), write the tests from the examples, then write the function yourself. A skeleton with blanks is a hint if you&#39;re stuck, not the default. Then Copilot reviews your <a href="./../../resources/glossary.html#diff">diff</a>: you keep the thinking, and the AI helps you check it.</p><p><strong>Test your own logic.</strong> In week 4 you wrote a first <a href="./../../resources/glossary.html#test-manual-and-automated">automated test</a> with <code>node --test</code>, and in week 6 you checked first with one. Project 1 needs at least three, of its <strong><a href="./../../resources/glossary.html#pure-function">pure functions</a></strong>: functions that use only their inputs, with no <code>document</code>, no <code>localStorage</code> and no clock. Good tests come from your spec and your edge cases: the normal case, a boundary (exactly the limit, one over), and the empty case. Two habits make tests trustworthy:</p><ul><li><strong>See every test fail once.</strong> Break the function on purpose and watch the right test go red. A test you&#39;ve never seen fail may not be checking anything (<a href="./../../resources/glossary.html#redgreen-testing">red/green testing</a>).</li><li><strong>Write tests apart from the code.</strong> When an AI writes tests after faulty code, the tests tend to agree with the faults: in a 2026 study they caught 14% of faults, against 25% for tests written independently (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>; <a href="./../../resources/safe-loop.html#check-first">check first</a>). Never change a test just to make it pass.</li></ul><p>One JavaScript trap: <code>[1, 2] === [1, 2]</code> is <code>false</code>, because <code>===</code> asks whether they&#39;re the same array, while Python&#39;s <code>[1, 2] == [1, 2]</code> is <code>True</code>. To compare arrays and objects by their contents, use <code>assert.deepEqual</code>.</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><ul><li><strong>Exit ticket</strong> (🔴 AI off, graded on completion, not correctness): week 8 questions. One question asks about your week 6 Project 1 v1, from memory.</li><li><strong>Oral walkthrough 1</strong> (10 minutes, 🔴 AI off, on your own Project 1), in either studio this week or in office hours. The questions are in the Walkthrough 1 section of the <a href="./../../assessment/oral-walkthroughs.html">oral walkthroughs</a> page.</li></ul><p>To check yourself first: open one of your tests, say what it checks, and name a change that would make it fail. Then explain the difference between <code>git restore</code> and <code>git revert</code>.</p><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p><strong>Project 1 final</strong> (about 5½ hours, including project time): everything in the Due row above. Details: <a href="./homework.html">homework</a>. Grading: <a href="./../../assessment/rubrics.html#project-1">Project 1 rubric</a>.</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>If this fails</th><th>Do this</th></tr></thead><tbody><tr><td>Codespaces won&#39;t start or you&#39;re out of free hours</td><td>Stop your other codespaces at <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a>. Otherwise use <a href="./../../setup/local-setup.html">local setup</a>, or pair with a partner in their codespace. A walkthrough can run from local setup, or be rescheduled without penalty</td></tr><tr><td>Copilot is unavailable or out of credits</td><td>Use your chat assistant in a browser tab, pasting the diff you want reviewed (<a href="./../../TOOLS.html">Tool Handout</a>)</td></tr><tr><td><code>npm</code> isn&#39;t found or Node is too old</td><td>In a Codespace it&#39;s preinstalled. Elsewhere you need Node.js 22 LTS (minimum 20.12): <a href="./../../resources/troubleshooting.html#npm-command-not-found-or-the-wrong-node-version">troubleshooting</a></td></tr><tr><td>GitHub Pages is slow to update</td><td>Check the <strong>Actions</strong> tab</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Node.js test runner documentation: <a href="https://nodejs.org/api/test.html" target="_blank" rel="noreferrer">https://nodejs.org/api/test.html</a>, and the <code>assert</code> module: <a href="https://nodejs.org/api/assert.html" target="_blank" rel="noreferrer">https://nodejs.org/api/assert.html</a></li><li>The Anthropic study, including the AI-use patterns of high scorers: <a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">https://www.anthropic.com/research/AI-assistance-coding-skills</a></li><li><a href="./../../resources/without-ai-skills.html">Six Skills You Must Show Without AI</a>, with practice for each</li></ul>',30)])])}const f=t(s,[["render",i]]);export{g as __pageData,f as default};
